        JPanel hero=new JPanel(new BorderLayout(24,12)){int phase=0;final javax.swing.Timer timer=new javax.swing.Timer(55,e->{phase=(phase+1)%360;repaint();});{timer.start();}public void removeNotify(){timer.stop();super.removeNotify();}protected void paintComponent(Graphics g){super.paintComponent(g);Graphics2D x=(Graphics2D)g.create();x.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);x.setPaint(new GradientPaint(0,0,new Color(34,25,54),getWidth(),getHeight(),new Color(15,26,37)));x.fillRoundRect(0,0,getWidth(),getHeight(),24,24);x.setColor(new Color(166,130,255,35));int d=130+(int)(8*Math.sin(Math.toRadians(phase)));x.fillOval(getWidth()-205-d/2,getHeight()/2-d/2,d,d);x.setColor(new Color(166,130,255,90));x.setStroke(new BasicStroke(1.5f));x.drawOval(getWidth()-215-d/2,getHeight()/2-d/2,d+20,d+20);x.dispose();}};
        hero.setOpaque(false);hero.setBorder(new CompoundBorder(new LineBorder(new Color(91,72,132),1,true),new EmptyBorder(30,32,30,32)));JPanel left=column();left.add(label("✦  VRON CLIENT  /  BLACK EDITION 2.3",11,ACCENT,true));left.add(Box.createVerticalStrut(15));left.add(label("Играй на своём уровне.",32,TEXT,true));left.add(Box.createVerticalStrut(9));left.add(label("Настоящее игровое ядро • Fabric • Forge • Modrinth • CurseForge",12,new Color(190,184,210),false));left.add(Box.createVerticalStrut(26));JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT,0,0));actions.setOpaque(false);JButton play=button("▶   "+(selectedVersion.isBlank()?"ВЫБРАТЬ ВЕРСИЮ":Files.exists(instance().resolve("versions").resolve(selectedVersion).resolve(selectedVersion+".json"))?"ЗАПУСТИТЬ ИГРУ":"УСТАНОВИТЬ MINECRAFT"));play.addActionListener(e->installSelected());JButton choose=ghost("Версии и профили");choose.addActionListener(e->showPage("versions"));actions.add(play);actions.add(Box.createHorizontalStrut(10));actions.add(choose);left.add(actions);hero.add(left,BorderLayout.CENTER);
        JPanel emblem=new JPanel();emblem.setOpaque(false);emblem.setLayout(new BoxLayout(emblem,BoxLayout.Y_AXIS));emblem.setBorder(new EmptyBorder(0,12,0,10));JLabel crest=new JLabel(scaledLogo(176));crest.setAlignmentX(Component.CENTER_ALIGNMENT);emblem.add(crest);JLabel wordmark=label("V R O N",12,new Color(205,190,255),true);wordmark.setAlignmentX(Component.CENTER_ALIGNMENT);emblem.add(Box.createVerticalStrut(-8));emblem.add(wordmark);hero.add(emblem,BorderLayout.EAST);hero.setPreferredSize(new Dimension(800,246));c.add(hero);c.add(Box.createVerticalStrut(16));
        JPanel stats=new JPanel(new GridLayout(1,4,10,0));stats.setOpaque(false);stats.add(stat("ВЫБРАННАЯ ВЕРСИЯ",selectedVersion.isBlank()?"Не выбрана":selectedVersion,"◈"));stats.add(stat("СБОРКА",selectedBuild,"▦"));stats.add(stat("ПРОФИЛЬ",player,"◉"));stats.add(stat("ПАМЯТЬ",ram+" MB","▤"));c.add(stats);c.add(Box.createVerticalStrut(16));
        JPanel lower=new JPanel(new GridLayout(1,2,12,0));lower.setOpaque(false);JPanel quick=card();quick.setLayout(new BorderLayout());quick.add(label("БЫСТРЫЙ ДОСТУП",11,ACCENT,true),BorderLayout.NORTH);JPanel tiles=new JPanel(new GridLayout(3,1,0,8));tiles.setOpaque(false);tiles.setBorder(new EmptyBorder(12,0,0,0));tiles.add(quickTile("Каталог модов","Открыть Modrinth и CurseForge",()->showPage("mods")));tiles.add(quickTile("Мои сборки","Отдельные игровые окружения",()->showPage("builds")));tiles.add(quickTile("Настройки","Аккаунт, память и интеграции",()->showPage("settings")));quick.add(tiles,BorderLayout.CENTER);lower.add(quick);
